/** Which trim ring each First Empire step uses (step year → key in BYZ_TRIM_RINGS). */
export const BYZ_TRIM_FOR_STEP = {"681": "T681", "705": "T705", "809": "T809", "812": "T812", "842": "T842", "864": "T842", "893": "T842", "917": "T917", "924": "T917", "927": "T917", "933": "T917", "971": "T971", "986": "T986", "1001": "T971", "1003": "T1003", "1014": "T1003", "1018": "T1003"};

export const bulgariaShapeFixes = {
  'byzantine-empire': ['byzantine-core (680–1019) cut back from the First Bulgarian Empire at each of its steps; 800 keyframe replaced'],
};

const sameRing = (a, b) => a.length === b.length && a.every((p, i) => p[0] === b[i][0] && p[1] === b[i][1]);

/** Replace the Byzantine 800 keyframe with trimmed keyframes for 680–1019 (one-year steps). */
export function applyBulgariaShapeFixes(entities) {
  const ent = entities.find((e) => e.id === 'byzantine-empire');
  if (!ent) throw new Error('bulgaria fixes: no entity byzantine-empire');
  const i800 = ent.overlays.findIndex((o) => o.year === 800);
  const kf1025 = ent.overlays.find((o) => o.year === 1025);
  if (i800 < 0 || !kf1025) throw new Error('bulgaria fixes: byzantine-empire missing 800 or 1025');
  if (ent.overlays.some((o) => o.year > 565 && o.year < 1025 && o.year !== 800)) throw new Error('bulgaria fixes: unexpected byzantine keyframes in 565–1025');
  const kf800 = ent.overlays[i800];
  const core = kf800.regions.find((r) => typeof r !== 'string' && r.id === 'byzantine-core');
  if (!core || !core.ring || !sameRing(core.ring, BYZ_BASE_800)) throw new Error('bulgaria fixes: byzantine 800 core ring changed — regenerate BYZ_TRIM_RINGS');
  const others = kf800.regions.filter((r) => r !== core);
  const kf = (year, label, ring) => ({ year, label, approximation: kf800.approximation, regions: [{ id: 'byzantine-core', name: core.name, ring }, ...others] });
  const steps = BG_STEPS['first-bulgarian-empire'];
  const out = [{ ...kf800, year: 680, label: 'Byzantine Balkans before the Bulgar treaty' }];
  steps.forEach(([y], i) => {
    const ring = BYZ_TRIM_RINGS[BYZ_TRIM_FOR_STEP[y]];
    if (!ring) throw new Error(`bulgaria fixes: no Byzantine trim for ${y}`);
    const prev = out[out.length - 1];
    if (i > 0 && prev.regions[0].ring === ring) return; // same shape: no new keyframe
    if (i > 0 && y - 1 > prev.year) out.push(kf(y - 1, prev.label, prev.regions[0].ring));
    out.push(kf(y, 'Byzantine Balkans beside Bulgaria', ring));
  });
  const last = out[out.length - 1];
  if (last.year < 1018) out.push(kf(1018, last.label, last.regions[0].ring));
  out.push({ ...kf1025, year: 1019, label: 'Basil II: Bulgaria annexed', regions: [...kf1025.regions, ...others] });
  ent.overlays.splice(i800, 1, ...out);
}
